const EQUIPMENT=[['Ocak','🍳'],['Fırın','♨️'],['Mikrodalga','📡'],['Air fryer','🍟'],['Blender / rondo','🥤'],['Tost makinesi','🥪']];
// Tahmini ekipman sınıflandırması: tarifte belirtilen yönteme dayanır; belirsiz tariflerde "Ekipman belirtilmemiş" gösterilir.
function recipeEquipment(r){const t=(r.name+' '+(r.note||'')).toLocaleLowerCase('tr-TR');
 if(/fırında|fırın |fırın$|fırınlan/.test(t))return ['Fırın'];
 if(/tost|burger/.test(t))return ['Tost makinesi'];
 if(/smoothie|protein içece|detoks içece|kahvaltı içece/.test(t))return ['Blender / rondo'];
 if(/omlet|pankek|sote|pilav|makarna|çorba|köfte|mercimek yemeği|lor tava|tavuk sarma|sarımsaklı tavuk|pesto soslu tavuk|waffle/.test(t))return ['Ocak'];
 return [];
}
const equipped=r=>{const req=recipeEquipment(r),own=state.profile.equipment||[];return !req.length||req.every(x=>own.includes(x))};
const eqLabel=r=>{let e=recipeEquipment(r);return e.length?e.join(', '):'Ekipman belirtilmemiş'};
function toggleEquipment(n){const a=state.profile.equipment||[];state.profile.equipment=a.includes(n)?a.filter(x=>x!==n):[...a,n];save();render()}
function setEquipmentFilter(n){state.equipmentFilter=n;render()}
function equipmentOptions(){return `<div class="options">${EQUIPMENT.map(([n,em])=>`<button class="option ${(state.profile.equipment||[]).includes(n)?'selected':''}" onclick="toggleEquipment('${n}')"><span>${em} &nbsp; ${n}</span><span class="check">${(state.profile.equipment||[]).includes(n)?'✓':'＋'}</span></button>`).join('')}</div>`}
function modalEquipment(){return `<h1>Mutfağında neler var? 🍳</h1><p class="sub">Birden fazla seçebilirsin. Bunları Tarifler filtresinde ve haftalık planda kullanacağız.</p>${equipmentOptions()}<button class="primary full" style="margin-top:18px" onclick="state.profile.equipmentConfigured=true;closeModal();save();render()">Kaydet</button>`}
const defaults={step:0,done:false,profile:{cuisines:[],exclude:[],time:30,meals:3,repeat:'Bazen',cal:2300,equipment:[],equipmentConfigured:false},tab:'home',stock:[],shop:[],logs:[],plan:[],custom:[],filter:'Tümü',search:'',modal:null,servings:1,budget:2300,prices:[],purchases:[]};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('mise_state')||'{}')}}catch{state={...defaults}};
state.profile={...defaults.profile,...(state.profile||{})};state.equipmentFilter||='Uygun olanlar';state.prices ||= [];state.purchases ||= [];state.budget ||= 2300;
const save=()=>localStorage.setItem('mise_state',JSON.stringify({...state,modal:null,search:'',filter:'Tümü'}));
function initSample(){if(state.stock.length)return;state.stock=[{id:1,name:'Tavuk göğsü',qty:850,unit:'g',bought:today(),expires:addDays(2)},{id:2,name:'Yumurta',qty:8,unit:'adet',bought:today(),expires:addDays(16)},{id:3,name:'Süt',qty:750,unit:'ml',bought:today(),expires:addDays(3)},{id:4,name:'Domates',qty:4,unit:'adet',bought:today(),expires:addDays(3)},{id:5,name:'Kaşar peyniri',qty:200,unit:'g',bought:today(),expires:addDays(12)},{id:6,name:'Yulaf ezmesi',qty:350,unit:'g',bought:today(),expires:addDays(180)},{id:7,name:'Muz',qty:3,unit:'adet',bought:today(),expires:addDays(4)},{id:8,name:'Zeytinyağı',qty:400,unit:'ml',bought:today(),expires:addDays(240)}];save()}
const qtyOf=(n,u)=>state.stock.filter(s=>s.name.toLowerCase()===n.toLowerCase()&&s.unit===u).reduce((a,b)=>a+b.qty,0);
function needs(r,n=1){return r.ing.map(([name,q,unit])=>({name,need:q/r.serv*n,unit,have:qtyOf(name,unit)}))}
function matching(r){const ns=needs(r);return ns.length?ns.filter(x=>x.have>=x.need).length/ns.length:0}
const excluded=r=>state.profile.exclude.some(x=>r.ing.some(i=>i[0].toLocaleLowerCase('tr').includes(x.toLocaleLowerCase('tr'))));
function rank(r){return matching(r)*100+(state.profile.cuisines.includes(r.cuisine)?12:0)-Math.abs(r.kcal-650)/120-((r.time>state.profile.time)?16:0)+r.ing.filter(i=>state.stock.some(s=>s.name===i[0]&&dateDelta(s.expires)<=3)).length*12}
const sortedRecipes=()=>recipes.filter(r=>!excluded(r)&&(!state.profile.equipmentConfigured||equipped(r))).sort((a,b)=>rank(b)-rank(a));
function notify(s){const o=document.createElement('div');o.className='toast';o.textContent=s;$('.phone').append(o);setTimeout(()=>o.remove(),3400)}
const title=(left,right='')=>`<div class="topbar"><div class="logo">mise<b>.</b></div><button class="iconbtn" onclick="openModal('profile')">☻</button></div>`;
const bottom=()=>`<nav class="nav">${[['home','⌂','Bugün'],['recipes','♨','Tarifler'],['fridge','▤','Dolabım'],['shop','▣','Market'],['plan','▦','Planım']].map(([k,ico,label])=>`<button class="${state.tab===k?'active':''}" onclick="go('${k}')"><i>${ico}</i>${label}</button>`).join('')}</nav>`;
function go(tab){state.tab=tab;state.modal=null;state.search='';state.filter='Tümü';render();save()}
function render(){app.innerHTML=state.done?renderApp():renderOnboard(); if(state.modal)renderModal();}
function renderApp(){return `<div class="page">${title()}${({home:homePage,recipes:recipePage,fridge:fridgePage,shop:shopPage,plan:planPage})[state.tab]()}</div>${bottom()}${['fridge','shop'].includes(state.tab)?`<button class="fab" aria-label="Ekle" onclick="openModal('${state.tab==='fridge'?'stock':'shopadd'}')">＋</button>`:''}`}
function homePage(){const used=state.logs.filter(x=>x.date===today()).reduce((s,x)=>s+x.kcal,0),t=state.profile.cal,exp=state.stock.filter(s=>dateDelta(s.expires)<=3&&s.qty>0).sort((a,b)=>dateDelta(a.expires)-dateDelta(b.expires));const r=sortedRecipes().slice(0,5);return `<span class="eyebrow">${new Date().toLocaleDateString('tr-TR',{weekday:'long',day:'numeric',month:'long'}).toLocaleUpperCase('tr')}</span><h1>Bugün kendine<br>iyi bak. 🌿</h1><p class="sub" style="margin:0 0 19px">Güzel yemekler ve küçük adımlar.</p><section class="hero"><div class="eyebrow">GÜNLÜK KALORİ HEDEFİN</div><h1>${Math.max(0,t-used).toLocaleString('tr')} <small>kcal kaldı</small></h1><div class="progress"><span style="width:${Math.min(100,used/t*100)}%"></span></div><div class="row" style="font-size:12px"><span>${used} tüketildi</span><span>${t} hedef</span></div><div class="hero-footer">✦ ${state.logs.filter(x=>x.date===today()).length} öğün kaydettin · ${Math.round(state.logs.filter(x=>x.date===today()).reduce((s,x)=>s+x.pro,0))} g protein</div></section>${exp.length?`<div class="alert" onclick="go('fridge')"><div class="emoji">⏳</div><div><b>${esc(exp[0].name)} için zaman daralıyor</b><p>${dateDelta(exp[0].expires)<0?'Tüketim tarihi geçmiş olabilir.':dateDelta(exp[0].expires)===0?'Tüketim tarihi bugün.':'Tahmini '+dateDelta(exp[0].expires)+' gün kaldı.'} Dolabını kontrol et.</p></div><span>›</span></div>`:''}${!state.profile.equipmentConfigured?`<div class="alert" onclick="openModal('equipment')"><div class="emoji">🍳</div><div><b>Mutfağında hangi aletler var?</b><p>Tarifleri sana uygun filtrelemek için seç.</p></div><span>›</span></div>`:''}<div class="row section"><h2>Bugünün öğünleri</h2><button class="linkbtn" onclick="go('plan')">Plan oluştur →</button></div>${[['☀️','Kahvaltı'],['🌤','Öğle'],['🌙','Akşam']].slice(0,state.profile.meals<=2?2:3).map(([e,n],i)=>{let l=state.logs.find(x=>x.date===today()&&x.meal===n);return `<div class="card meal" onclick="openModal('pick','${n}')"><div class="foodico">${e}</div><div class="mealtext"><b>${n}</b><span>${l?esc(l.name):['Güne güzel başla','Enerjini topla','Günü tamamla'][i]}</span></div><span class="status">${l?'✓ '+l.kcal+' kcal':'+ Ekle'}</span></div>`}).join('')}<div class="row section"><h2>Senin için seçtik</h2><button class="linkbtn" onclick="go('recipes')">Tüm tarifler →</button></div><div class="cardslide">${r.map(tile).join('')}</div><div class="row section"><h2>Mutfağın bir bakışta</h2><button class="linkbtn" onclick="go('fridge')">Dolabım →</button></div><div class="stats"><div class="stat"><b>${state.stock.length}</b><span>malzeme</span></div><div class="stat"><b>${exp.length}</b><span>yakın tarihli</span></div><div class="stat"><b>${state.shop.filter(x=>!x.done).length}</b><span>alınacak ürün</span></div></div>`}
const tile=r=>`<div class="recipe-tile" onclick="openModal('recipe',${r.id})"><div class="tilepic">${r.icon}<span class="tag">${matching(r)===1?'✓ Evde var':Math.round(matching(r)*100)+'% evde'}</span></div><div class="tilebody"><b>${esc(r.name)}</b><p>${r.kcal} kcal · ${r.pro}g protein · ${r.time} dk</p></div></div>`;
function recipePage(){let filter=state.filter,q=state.search.toLocaleLowerCase('tr'),ls=[...recipes].filter(r=>!excluded(r)).sort((a,b)=>rank(b)-rank(a)).filter(r=>((state.equipmentFilter==='Tüm ekipmanlar'||!state.profile.equipmentConfigured||(state.equipmentFilter==='Uygun olanlar'?equipped(r):recipeEquipment(r).includes(state.equipmentFilter))))&&(filter==='Tümü'||filter==='Evde var'&&matching(r)===1||r.cat===filter||r.cuisine===filter)&&r.name.toLocaleLowerCase('tr').includes(q));return `<span class="eyebrow">LEZZET KÜTÜPHANEN</span><h1>Ne pişirsek? 🍽️</h1><p class="sub">Kalorine, zevkine ve dolabına göre öneriler.</p><div class="search"><span>⌕</span><input placeholder="Tarif ara..." value="${esc(state.search)}" oninput="searchRecipes(this.value)"></div><div class="chips">${['Uygun olanlar','Tüm ekipmanlar',...EQUIPMENT.map(x=>x[0])].map(t=>`<button class="chip ${state.equipmentFilter===t?'active':''}" onclick="setEquipmentFilter('${t}')">${t}</button>`).join('')}</div><div class="chips">${['Tümü','Evde var','Kahvaltı','Ana yemek','Türk','İtalyan','Amerikan'].map(t=>`<button class="chip ${filter===t?'active':''}" onclick="setFilter('${t}')">${t}</button>`).join('')}</div><div class="row section"><h2>${filter==='Tümü'?'Sana özel öneriler':esc(filter)}</h2><span class="sub">${ls.length} tarif</span></div>${ls.length?ls.map(r=>`<div class="recipe-row" onclick="openModal('recipe',${r.id})"><div class="pic">${r.icon}</div><div class="content"><b>${esc(r.name)}</b><p>${r.kcal} kcal/porsiyon · ${r.serv} porsiyonluk · ${r.time} dk · ${esc(eqLabel(r))}</p><span class="tag">${matching(r)===1?'Tüm malzemeler evde':Math.round(matching(r)*100)+'% malzeme evde'}</span></div><span class="chev">›</span></div>`).join(''):`<div class="empty">Burada henüz tarif yok.</div>`}<p class="sub" style="margin-top:22px">Başlangıç tarifleri, yüklediğin Fit Tarifler kitabındaki besin değerlerinden derlenmiştir. Bazı malzeme ölçüleri yaklaşık veya alternatiflidir.</p>`}
function setFilter(x){state.filter=x;render()};function searchRecipes(x){state.search=x; const sel=$('#app');render(); const inp=$('.search input');inp?.focus();inp?.setSelectionRange(x.length,x.length)}
function fridgePage(){const exp=state.stock.filter(s=>dateDelta(s.expires)<=3&&s.qty>0);return `<span class="eyebrow">MUTFAĞIM</span><h1>Buzdolabım 🧊</h1><p class="sub">Her malzeme yerli yerinde. Hiçbir şey boşa gitmesin.</p><div class="stats"><div class="stat"><b>${state.stock.length}</b><span>ürün</span></div><div class="stat"><b>${exp.length}</b><span>kontrol et</span></div><div class="stat"><b>${state.stock.filter(x=>x.qty<=2).length}</b><span>azalan stok</span></div></div>${exp.length?`<div class="alert" onclick="go('recipes')"><div class="emoji">💡</div><div><b>Önce bunları değerlendirelim</b><p>${exp.slice(0,3).map(x=>x.name).join(', ')} · Bunlara uygun tariflere bak.</p></div><span>›</span></div>`:''}<div class="row section"><h2>Malzemelerin</h2><button class="linkbtn" onclick="openModal('stock')">+ Yeni ekle</button></div>${state.stock.length?`<div class="card">${[...state.stock].sort((a,b)=>dateDelta(a.expires)-dateDelta(b.expires)).map(s=>{let d=dateDelta(s.expires);return `<div class="stock-row" onclick="openModal('editstock',${s.id})"><div class="stock-emoji">${emoji(s.name)}</div><div class="stock-main"><b>${esc(s.name)}</b><p>${+s.qty.toFixed(1)} ${s.unit} kaldı · ${d<0?'Tarih geçti':d===0?'Bugün':d+' gün'}</p></div>${d<0?'<span class="badge-over">Tarih geçti</span>':d<=3?'<span class="badge-warn">Yakında</span>':'<span style="color:#93aa98">›</span>'}</div>`}).join('')}</div>`:`<div class="empty"><div class="emptyico">🧺</div><b>Dolabın henüz boş</b><p>Market alışverişlerini ekle, tarifler seninle eşleşsin.</p><button class="primary" onclick="openModal('stock')">İlk malzemeni ekle</button></div>`}<div class="mutedbox">ℹ️ Tarihler yalnızca hatırlatmadır. Ambalajdaki son tüketim tarihi, saklama sıcaklığı ve ürünün durumu esas alınmalıdır. Tarihi geçmiş riskli ürünler kullanılmamalıdır.</div>`}
function money(n){return Number(n||0).toLocaleString('tr-TR',{minimumFractionDigits:0,maximumFractionDigits:2})+' ₺'}
function normal(n){return String(n||'').toLocaleLowerCase('tr-TR').trim().replace(/\s+/g,' ')}
function standard(q,u){return u==='kg'?[q*1000,'g']:u==='L'?[q*1000,'ml']:[q,u]}
function priceFor(name,unit){let rows=state.prices.filter(p=>normal(p.name)===normal(name));let costs=rows.map(p=>{let [q,u]=standard(p.qty,p.unit),[v,w]=standard(1,unit);return u===w&&q>0?{v:p.total/q*v,date:p.date}:null}).filter(Boolean).sort((a,b)=>b.date.localeCompare(a.date));return costs.length?costs.slice(0,3).reduce((sum,p)=>sum+p.v,0)/Math.min(3,costs.length):null}
function estimated(s){let unitCost=priceFor(s.name,s.unit);return unitCost===null?null:unitCost*s.qty}
function purchaseRows(){return state.prices.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,16)}
function recordPrice(name,qty,unit,total,date=today(),stock=false){qty=Number(qty);total=Number(total);if(!name||!(qty>0)||!(total>=0))return false;state.prices.push({id:Date.now()+Math.random(),name:name.trim(),qty,unit,total,date});state.purchases.push({id:Date.now()+Math.random(),name:name.trim(),qty,unit,total,date});if(stock){let [amount,u]=standard(qty,unit);let item=state.stock.find(x=>normal(x.name)===normal(name)&&x.unit===u);if(item)item.qty+=amount;else state.stock.push({id:Date.now()+Math.random(),name:name.trim(),qty:amount,unit:u,bought:date,expires:addDays(5)})}return true}
function savePrice(){let name=$('#price-name').value.trim(),qty=Number($('#price-qty').value),unit=$('#price-unit').value,total=Number($('#price-total').value),date=$('#price-date').value;let stock=$('#price-stock').checked;if(!recordPrice(name,qty,unit,total,date,stock))return notify('Ürün, miktar ve geçerli fiyat gir.');closeModal();save();render();notify('✓ Fiyat hafızasına kaydedildi')}
function removePrice(id){state.prices=state.prices.filter(x=>x.id!==id);save();render()}
function receiptPage(){return `<div class="card"><div class="row"><b>🧾 Fişten fiyat öğren</b><button class="linkbtn" onclick="openModal('receipt')">Fiş yükle →</button></div><p class="sub">Fotoğraf veya fişteki yazıyı ekle; satırları kontrol edip ürünleri kaydet.</p><button class="outline full" onclick="openModal('price')">＋ Manuel fiyat kaydet</button></div><div class="row section"><h2>Fiyat hafızam</h2><span class="sub">Son ${Math.min(16,state.prices.length)} kayıt</span></div>${purchaseRows().length?`<div class="card">${purchaseRows().map(x=>`<div class="stock-row"><div class="stock-emoji">${emoji(x.name)}</div><div class="stock-main"><b>${esc(x.name)}</b><p>${x.qty} ${x.unit} · ${esc(x.date)} · ${money(x.total)} ${standard(x.qty,x.unit)[1]==='g'?`· ${money(x.total/standard(x.qty,x.unit)[0]*1000)}/kg`:''}</p></div><button class="ghost" onclick="removePrice(${x.id})">×</button></div>`).join('')}</div>`:`<p class="sub">Fiyat kaydı yok. İlk market alışverişini ekle; sonraki planın bu fiyatları kullanacak.</p>`}</div>`}
function saveBudget(){let n=Number($('#week-budget').value);if(!(n>0))return notify('Pozitif bir bütçe gir.');state.budget=n;save();render();notify('Haftalık bütçe güncellendi')}
function estimatedSummary(){let known=0,unknown=[];for(let x of state.shop.filter(x=>!x.done)){let cost=estimated(x);if(cost===null)unknown.push(x.name);else known+=cost}return {known,unknown}}
function modalPrice(){return `<h1>Fiyat kaydet 🧾</h1><p class="sub">Fişindeki miktarı ve o ürün için ödediğin tutarı yaz.</p><div class="field"><label>Ürün</label><input id="price-name" placeholder="Tavuk göğsü"></div><div class="fieldgrid"><div class="field"><label>Miktar</label><input type="number" id="price-qty" step="any" min="0" value="1"></div><div class="field"><label>Birim</label><select id="price-unit">${['kg','g','adet','L','ml'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><div class="fieldgrid"><div class="field"><label>Toplam ödenen (₺)</label><input id="price-total" type="number" step="any" min="0"></div><div class="field"><label>Alış tarihi</label><input id="price-date" type="date" value="${today()}"></div></div><label class="field"><input type="checkbox" id="price-stock"> Aynı zamanda dolabıma ekle (tüketim tarihini dolabımdan kontrol edeceğim)</label><button class="primary full" onclick="savePrice()">Fiyatı kaydet</button>`}
function modalReceipt(){return `<h1>Fişimi oku 🧾</h1><p class="sub">Fotoğraftaki metni cihazında tanımayı dener. İlk kullanımda OCR kütüphanesi internetten yüklenir. Türkçe fişler hatalı okunabilir.</p><div class="field"><label>Fiş fotoğrafı</label><input id="receipt-file" type="file" accept="image/*" capture="environment"></div><button class="outline full" onclick="readReceipt()">Fotoğraftan metin çıkar</button><p id="receipt-status" class="sub"></p><div class="field"><label>Fişteki yazı (düzeltebilirsin)</label><textarea id="receipt-text" rows="7" placeholder="TAVUK GOGUS 1,200 KG 360,00
DOMATES 0,500 KG 40,00"></textarea></div><button class="primary full" onclick="parseReceipt()">Ürünleri kontrol et →</button>`}
async function readReceipt(){const file=$('#receipt-file').files[0];if(!file)return notify('Önce fiş fotoğrafı seç.');let status=$('#receipt-status');status.textContent='Metin tanıma yükleniyor…';try{if(!window.Tesseract){await new Promise((ok,no)=>{let el=document.createElement('script');el.src='https://cdn.jsdelivr.net/npm/tesseract.js@5/dist/tesseract.min.js';el.onload=ok;el.onerror=no;document.head.appendChild(el)})}status.textContent='Fiş okunuyor…';let res=await Tesseract.recognize(file,'tur+eng');$('#receipt-text').value=res.data.text;status.textContent='Metin çıkarıldı. Satırları düzenleyip kontrol et.'}catch(e){status.textContent='Fotoğraf okunamadı. Fişteki satırları aşağıya elle yazabilirsin.'}}
function parseReceipt(){let lines=$('#receipt-text').value.split(/\n/).map(x=>x.trim()).filter(Boolean),rows=[];for(let line of lines){let m=line.match(/^(.+?)\s+(\d+[.,]\d+|\d+)\s*(KG|GR|G|ADET|AD|LT|L|ML)\s+([\d.,]+)(?:\s*(?:TL|₺))?$/i);if(!m)continue;let qty=Number(m[2].replace(',','.')),unit=m[3].toLowerCase(),raw=m[4];let total=Number(raw.replace(/\.(?=\d{3}(?:\D|$))/g,'').replace(',','.'));unit=unit==='gr'?'g':unit==='ad'?'adet':unit==='lt'?'L':unit==='kg'?'kg':unit==='l'?'L':unit;if(qty>0&&total>=0)rows.push({name:m[1],qty,unit,total})}state.receiptDraft=rows;closeModal();openModal('receiptReview')}
function modalReceiptReview(){let rows=state.receiptDraft||[];return `<h1>Fişi kontrol et</h1><p class="sub">Yalnız tanınan satırlar gösterilir. Ürün, miktar ve tutarları düzelterek kaydet. Okunmayanları manuel girebilirsin.</p>${rows.length?rows.map((r,i)=>`<div class="card" style="margin-bottom:10px;padding:12px"><div class="field"><label>Ürün</label><input id="receipt-name-${i}" value="${esc(r.name)}"></div><div class="fieldgrid"><div class="field"><label>Miktar</label><input type="number" step="any" id="receipt-qty-${i}" value="${r.qty}"></div><div class="field"><label>Birim</label><select id="receipt-unit-${i}">${['kg','g','adet','L','ml'].map(x=>`<option ${r.unit===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="field"><label>Fiyat (₺)</label><input type="number" step="any" id="receipt-total-${i}" value="${r.total}"></div></div>`).join(''):'<div class="mutedbox">Fişteki satırlar otomatik ayrılamadı. Örnek biçim: TAVUK 1,2 KG 360,00. İstersen tek tek manuel ekle.</div>'}<label><input id="receipt-addstock" type="checkbox"> Ürünleri dolaba da ekle</label>${rows.length?`<button class="primary full" onclick="saveReceiptReview()">${rows.length} ürünü kaydet</button>`:''}<button class="outline full" onclick="openModal('receipt')">← Metni düzelt</button><button class="onback full" onclick="openModal('price')">Manuel ürün ekle</button>`}
function saveReceiptReview(){let ok=0;for(let [i,r] of (state.receiptDraft||[]).entries()){if(recordPrice($('#receipt-name-'+i).value,Number($('#receipt-qty-'+i).value),$('#receipt-unit-'+i).value,Number($('#receipt-total-'+i).value),today(),$('#receipt-addstock').checked))ok++}delete state.receiptDraft;closeModal();save();render();notify(ok+' fiyat kaydedildi')}
function shopPage(){const pending=state.shop.filter(x=>!x.done),done=state.shop.filter(x=>x.done);return `<span class="eyebrow">ALIŞVERİŞ ASİSTANI</span><h1>Market listem 🛒</h1><p class="sub">Ne lazım, ne kadar lazım? Hepsi burada.</p><div class="card"><label>Haftalık market bütçem (₺)</label><div class="row"><input id="week-budget" type="number" min="1" step="any" style="width:58%;padding:10px" value="${state.budget}"><button class="outline" onclick="saveBudget()">Kaydet</button></div>${(()=>{let e=estimatedSummary();return `<p class="sub">Bilinen fiyatlarla tahmini alışveriş: <b>${money(e.known)}</b> · Kalan: <b>${money(state.budget-e.known)}</b>${e.unknown.length?`<br>${e.unknown.length} ürünün fiyatı bilinmiyor; gerçek toplam daha yüksek olabilir.`:''}</p>`})()}</div>${receiptPage()}<div class="card" style="background:#e5eddb;border:none"><b style="font-size:14px">Haftalık menüden eksikleri bul</b><p class="sub">Planındaki tariflerin malzemelerini dolabınla karşılaştır.</p><button class="primary" onclick="makeShopFromPlan()">✦ Eksikleri hesapla</button></div><div class="row section"><h2>Alınacaklar</h2><button class="linkbtn" onclick="openModal('shopadd')">+ Ekle</button></div>${pending.length?`<div class="card">${pending.map(s=>shopRow(s)).join('')}</div>`:`<div class="empty"><div class="emptyico">🛍️</div><b>Alışveriş listesi tertemiz</b><p>Eksikleri ekleyebilir veya bir tarifin malzemelerini listeye alabilirsin.</p></div>`}${done.length?`<div class="row section"><h2>Alındı (${done.length})</h2><button class="linkbtn" onclick="removeDone()">Temizle</button></div><div class="card">${done.map(shopRow).join('')}</div>`:''}<p class="sub">✓ Ürünü aldığında üzerine dokun. Miktarı ve son tüketim tarihini girerek dolabına aktar.</p>`}
function shopRow(s){return `<div class="shopitem"><input type="checkbox" ${s.done?'checked':''} onchange="toggleShop(${s.id})"><span style="${s.done?'text-decoration:line-through;color:#9da69d':''}">${emoji(s.name)} ${esc(s.name)}</span><small>${+s.qty.toFixed(1)} ${s.unit}<br>${estimated(s)===null?"Fiyat yok":money(estimated(s))}</small><button class="ghost" onclick="removeShop(${s.id})">×</button></div>`}
function planPage(){let ds=['Paz','Pzt','Sal','Çar','Per','Cum','Cmt'];return `<span class="eyebrow">YEDİ GÜNLÜK PLAN</span><h1>Haftalık menüm 📅</h1><p class="sub">Zevkine, fiyat hafızana ve mutfağına uygun, planlı bir hafta. Haftalık bütçe: ${money(state.budget)} · <span onclick="go('shop')" style="text-decoration:underline;cursor:pointer">Market'ten değiştir</span></p><div class="hero" style="padding:18px 20px"><span class="eyebrow">BU HAFTANIN PLANI</span><h1 style="font-size:25px">${state.plan.length} öğün hazır</h1><p style="font-size:12px;color:#d3e2d0;margin:4px 0 14px">İstediğin öğünü değiştirebilirsin.</p><button class="whitebtn" onclick="generatePlan()">✦ ${state.plan.length?'Planı yenile':'Bana menü hazırla'}</button></div><div class="row section"><h2>Öğün takvimi</h2><button class="linkbtn" onclick="makeShopFromPlan()">Market listesi →</button></div>${Array.from({length:7},(_,i)=>{let d=addDays(i),ps=state.plan.filter(x=>x.date===d);return `<div class="plannerrow"><div class="datepill"><b>${new Date(d+'T12:00:00').getDate()}</b><span>${ds[new Date(d+'T12:00:00').getDay()]}</span></div><div class="plancontent"><b>${i===0?'Bugün':new Date(d+'T12:00:00').toLocaleDateString('tr-TR',{weekday:'long'})}</b><p>${ps.length?ps.map(x=>recipes.find(r=>r.id===x.recipe)?.name).filter(Boolean).join(' · '):'Henüz planlanmadı'}</p></div><button class="ghost" onclick="openModal('pick','plan|${d}')">${ps.length?'Düzenle':'+ Ekle'}</button></div>`}).join('')}<div class="mutedbox">Plan için bütçe hesabı bilinen ürün fiyatlarına dayanır. Henüz fiyatı olmayan ürünler hesaba katılamaz; önce fiyat girip market listesini kontrol et. Kalori hedefine tam uyum garanti edilmez.</div><div class="mutedbox">Plan önerileri başlangıç aşamasında kural tabanlıdır; tıbbi veya profesyonel beslenme planı yerine geçmez.</div>`}
function renderOnboard(){let s=state.step,p=state.profile,options=[['Türk','🍲'],['İtalyan','🍝'],['Asya','🍜'],['Amerikan','🍔'],['Akdeniz','🫒'],['Diğer','🥗']],head=['En çok hangi mutfakları seversin?','Uzak durduğun malzemeler var mı?','Mutfakta ne kadar zaman geçirirsin?','Günde kaç öğün yemek istersin?','Aynı yemeği tekrar yemek nasıl?','Günlük kalori hedefini belirleyelim.','Mutfağında hangi aletler var?'],hint=['Birden fazla seçebilirsin.','Sevmediğin veya alerjin olan malzemeleri yaz.','Sana zamanına uygun tarifler sunalım.','Önerilerini günlük rutinine göre bölelim.','Yemek hazırlama planını buna göre düzenleyeceğiz.','Bunu istediğin zaman değiştirebilirsin.','Birden fazla seçebilirsin; sadece uygun tarifleri öne çıkaracağız.'];let body='';if(s===0)body=`<div class="options">${options.map(([n,em])=>`<button class="option ${p.cuisines.includes(n)?'selected':''}" onclick="toggleCuisine('${n}')"><span>${em} &nbsp; ${n}</span><span class="check">${p.cuisines.includes(n)?'✓':'＋'}</span></button>`).join('')}</div>`;if(s===1)body=`<div class="field"><label>Sevmediğin / tüketemediğin besinler (virgülle ayır)</label><textarea id="exclude" placeholder="Örn. mantar, brokoli, fıstık">${esc(p.exclude.join(', '))}</textarea></div><div class="mutedbox">Alerjilerin varsa buraya yazabilirsin. Tarifler filtrelenir; ancak çapraz bulaşma ve ürün etiketlerini ayrıca kontrol etmelisin.</div>`;if(s===2)body=`<div class="options">${[[15,'15 dakika · Hızlı tarifler'],[30,'30 dakika · Dengeli'],[60,'60 dakika · Rahat rahat'],[999,'Zaman önemli değil']].map(([v,n])=>`<button class="option ${p.time===v?'selected':''}" onclick="setPref('time',${v})">${n}<span class="check">${p.time===v?'✓':''}</span></button>`).join('')}</div>`;if(s===3)body=`<div class="options">${[[2,'2 ana öğün'],[3,'3 ana öğün'],[4,'3 ana + 1 ara öğün'],[5,'2 ana + 2 ara öğün']].map(([v,n])=>`<button class="option ${p.meals===v?'selected':''}" onclick="setPref('meals',${v})">${n}<span class="check">${p.meals===v?'✓':''}</span></button>`).join('')}</div>`;if(s===4)body=`<div class="options">${[['Evet','Hazır yemek yapmayı seviyorum'],['Bazen','Arada olabilir'],['Hayır','Her gün farklı yemek isterim']].map(([v,n])=>`<button class="option ${p.repeat===v?'selected':''}" onclick="setPref('repeat','${v}')">${n}<span class="check">${p.repeat===v?'✓':''}</span></button>`).join('')}</div>`;if(s===5)body=`<div class="field" style="margin-top:45px"><label>Günlük kalori hedefi (kcal)</label><input class="biginput" id="cal" type="number" min="1000" max="6000" value="${p.cal}"></div><div class="mutedbox">🎯 Örnek hedef: 2300 kcal. Bu değer yalnızca başlangıç önerisidir, sağlık uzmanının tavsiyesine göre ayarlanabilir.</div>`;if(s===6)body=equipmentOptions();return `<div class="onboard"><div class="logo">mise<b style="color:#b4cd8d">.</b></div><div class="onprogress">${Array.from({length:7},(_,i)=>`<span class="${i<=s?'active':''}"></span>`).join('')}</div><span class="eyebrow">SENİ TANIYALIM · ${s+1}/7</span><h1>${head[s]}</h1><p>${hint[s]}</p>${body}<div class="onfoot"><button class="primary full" onclick="nextOnboard()">${s===6?'Mutfağımı aç ✨':'Devam et →'}</button>${s>0?`<button class="onback full" onclick="state.step--;render();save()">← Geri dön</button>`:''}</div></div>`}
function toggleCuisine(n){let a=state.profile.cuisines;state.profile.cuisines=a.includes(n)?a.filter(x=>x!==n):[...a,n];render();save()};function setPref(n,v){state.profile[n]=v;render();save()}
function nextOnboard(){if(state.step===1)state.profile.exclude=($('#exclude')?.value||'').split(',').map(x=>x.trim()).filter(Boolean);if(state.step===5){let v=Number($('#cal').value);if(v<1000||v>6000)return notify('Lütfen 1000–6000 arası hedef gir.');state.profile.cal=v;}if(state.step===6){state.profile.equipmentConfigured=true;state.done=true;initSample()}else state.step++;save();render()}
function openModal(type,id){state.modal={type,id};state.servings=1;renderModal()};function closeModal(){state.modal=null;$('.overlay')?.remove();save()}
function renderModal(){ $('.overlay')?.remove();let m=state.modal;if(!m)return;let html='';if(m.type==='recipe')html=modalRecipe(recipes.find(x=>x.id===Number(m.id)));if(m.type==='stock'||m.type==='editstock')html=modalStock(m.type==='editstock'?state.stock.find(x=>x.id===m.id):null);if(m.type==='shopadd')html=modalShop();if(m.type==='buy')html=modalStock(null,state.shop.find(x=>x.id===m.id));if(m.type==='pick')html=modalPick(m.id);if(m.type==='profile')html=modalProfile();if(m.type==='equipment')html=modalEquipment();if(m.type==='price')html=modalPrice();if(m.type==='receipt')html=modalReceipt();if(m.type==='receiptReview')html=modalReceiptReview();const div=document.createElement('div');div.className='overlay';div.innerHTML=`<div class="sheet"><div class="sheet-grip"></div><div class="row" style="margin-bottom:12px"><span class="eyebrow">MISE · AKILLI MUTFAK</span><button class="iconbtn" onclick="closeModal()">×</button></div>${html}</div>`;div.addEventListener('click',e=>{if(e.target===div)closeModal()});$('.phone').appendChild(div)}
function modalRecipe(r){if(!r)return '';let n=state.servings,ns=needs(r,n);return `<div class="detail-hero">${r.icon}</div><span class="eyebrow">${r.cat.toUpperCase()} · ${r.time} DAKİKA</span><h1>${r.name}</h1><p class="sub">🍳 ${esc(eqLabel(r))}${state.profile.equipmentConfigured&&!equipped(r)?' · ⚠️ Seçtiğin ekipmanlarda yok':''}</p><p class="sub">📖 Kitaptaki tarif: <b>${r.serv} porsiyonluk</b> · ${r.kcal} kcal / porsiyon · sayfa ${r.sourcePage}</p><div class="row"><span class="tag">${Math.round(matching(r)*100)}% malzeme evde</span><div class="counter"><button onclick="serving(-1)">−</button><b>${n} porsiyon</b><button onclick="serving(1)">+</button></div></div><div class="stats"><div class="stat"><b>${Math.round(r.kcal*n)}</b><span>kcal</span></div><div class="stat"><b>${+(r.pro*n).toFixed(1)}g</b><span>protein</span></div><div class="stat"><b>${+(r.carb*n).toFixed(1)}g</b><span>karbonhidrat</span></div></div><div class="row section"><h2>Malzemeler</h2><span class="sub">${ns.filter(x=>x.have<x.need).length} eksik</span></div>${ns.map(x=>`<div class="ingredient"><span class="${x.have<x.need?'ingredients-missing':''}">${x.have<x.need?'○':'✓'} ${esc(x.name)}</span><em>${+x.need.toFixed(1)} ${x.unit} ${x.have<x.need?'· eksik':'· var'}</em></div>`).join('')}<div class="row section"><h2>Kitaptaki malzemeler</h2><span class="sub">Sayfa ${r.sourcePage}</span></div><p class="sub" style="white-space:pre-line">${esc(r.originalIngredients)}</p><div class="row section"><h2>Kitaptaki malzemeler</h2><span class="sub">Sayfa ${r.sourcePage}</span></div><p class="sub" style="white-space:pre-line">${esc(r.originalIngredients)}</p><div class="row section"><h2>Kitaptaki malzemeler</h2><span class="sub">Sayfa ${r.sourcePage}</span></div><p class="sub" style="white-space:pre-line">${esc(r.originalIngredients)}</p><div class="row section"><h2>Hazırlama notu</h2></div><p class="sub">${r.note}</p><div class="mutedbox">Malzeme miktarlarından bazıları yaklaşık/alternatiftir. Kalori ve makrolar kitaptaki porsiyon değerleridir; değişikliklerde farklılaşabilir.</div><button class="outline full" onclick="addMissing(${r.id})" style="margin:8px 0">🛒 Eksikleri market listeme ekle</button><button class="primary full" onclick="cook(${r.id})">✓ Yemeği yaptım · ${Math.round(r.kcal*n)} kcal</button><button class="onback full" onclick="planThis(${r.id})">📅 Haftalık plana ekle</button>`}
function serving(d){state.servings=Math.max(1,Math.min(12,state.servings+d));renderModal()}
function stockFields(item){let units=['g','kg','ml','L','adet','dilim','diş'];return `<div class="field"><label>Malzeme adı</label><input id="stock-name" placeholder="Örn. Tavuk göğsü" value="${esc(item?.name||'')}"></div><div class="fieldgrid"><div class="field"><label>Miktar</label><input id="stock-qty" type="number" step="any" min="0" value="${item?.qty||''}" placeholder="500"></div><div class="field"><label>Birim</label><select id="stock-unit">${units.map(u=>`<option ${u===(item?.unit||'g')?'selected':''}>${u}</option>`).join('')}</select></div></div><div class="fieldgrid"><div class="field"><label>Alış tarihi</label><input id="stock-bought" type="date" value="${item?.bought||today()}"></div><div class="field"><label>Tüketim tarihi</label><input id="stock-exp" type="date" value="${item?.expires||addDays(5)}"></div></div>`}
function modalStock(item=null,buy=null){return `<h1>${buy?'Satın aldım 🛒':item?'Malzemeyi düzenle':'Dolabıma ekle 🧊'}</h1><p class="sub">Miktarını ve ambalajdaki tüketim tarihini gir.</p>${stockFields(item||buy)}<button class="primary full" onclick="saveStock(${item?item.id:'null'},${buy?buy.id:'null'})">${item?'Değişiklikleri kaydet':'Dolabıma kaydet'}</button>${item?`<button class="onback full" onclick="deleteStock(${item.id})">Malzemeyi sil</button>`:''}`}
function modalShop(){return `<h1>Alışverişe ekle 🛒</h1><p class="sub">Almayı planladığın ürünü gir.</p><div class="field"><label>Malzeme</label><input id="shop-name" placeholder="Örn. Yoğurt"></div><div class="fieldgrid"><div class="field"><label>Miktar</label><input id="shop-qty" type="number" step="any" min="0" value="1"></div><div class="field"><label>Birim</label><select id="shop-unit">${['adet','g','kg','ml','L','dilim','diş'].map(x=>`<option>${x}</option>`).join('')}</select></div></div><button class="primary full" onclick="saveShop()">Listeye ekle</button>`}
function modalPick(id){let list=sortedRecipes().slice(0,9);return `<h1>Bir tarif seç 🍽️</h1><p class="sub">${String(id).startsWith('plan|')?'Planına ekle':'Öğününü kaydetmek için tarif seç.'}</p>${list.map(r=>`<div class="recipe-row" onclick="chooseRecipe(${r.id})"><div class="pic">${r.icon}</div><div class="content"><b>${r.name}</b><p>${r.kcal} kcal/porsiyon · ${r.serv} porsiyonluk</p></div><span>›</span></div>`).join('')}`}
function modalProfile(){return `<h1>Ayarlarım ⚙️</h1><div class="mini-row"><b>Günlük hedef</b><span>${state.profile.cal} kcal</span></div><div class="mini-row"><b>Öğün düzeni</b><span>${state.profile.meals} öğün</span></div><div class="mini-row"><b>Favori mutfaklar</b><span>${state.profile.cuisines.join(', ')||'Hepsi'}</span></div><div class="mini-row"><b>Tarif süresi</b><span>${state.profile.time===999?'Sınırsız':state.profile.time+' dk'}</span></div><div class="mini-row"><b>Pişirme ekipmanları</b><span>${(state.profile.equipment||[]).join(', ')||'Belirlenmedi'}</span></div><button class="outline full" style="margin-top:12px" onclick="openModal('equipment')">🍳 Mutfak aletlerimi düzenle</button><button class="outline full" style="margin-top:20px" onclick="reOnboard()">Tercihlerimi yeniden ayarla</button><button class="outline full" style="margin-top:10px" onclick="exportData()">Verilerimi indir (JSON)</button><div class="mutedbox">Bu prototipte kayıtlar yalnızca bu cihazın tarayıcısında tutulur. Sunucu, hesap veya gerçek zamanlı bulut senkronizasyonu yoktur.</div><button class="onback full" onclick="resetAll()">Tüm verileri sıfırla</button>`}
function reOnboard(){closeModal();state.done=false;state.step=0;render();save()}
function saveStock(id,buy){let name=$('#stock-name').value.trim(),qty=Number($('#stock-qty').value),unit=$('#stock-unit').value,bought=$('#stock-bought').value,expires=$('#stock-exp').value;if(!name||!qty||qty<=0||!bought||!expires)return notify('Malzeme ve miktar bilgilerini doldur.');let item={id:id||Date.now(),name,qty,unit,bought,expires};if(id){state.stock=state.stock.map(x=>x.id===id?item:x)}else state.stock.push(item);if(buy)state.shop=state.shop.map(x=>x.id===buy?{...x,done:true}:x);closeModal();save();render();notify('✓ Buzdolabın güncellendi')}
function deleteStock(id){state.stock=state.stock.filter(x=>x.id!==id);closeModal();render();save()}
function saveShop(){const name=$('#shop-name').value.trim(),qty=Number($('#shop-qty').value),unit=$('#shop-unit').value;if(!name||qty<=0)return notify('Ürün adı ve miktar gir.');addShop(name,qty,unit);closeModal();render();save();notify('Market listene eklendi')}
function addShop(name,qty,unit){let old=state.shop.find(s=>!s.done&&s.name===name&&s.unit===unit);if(old)old.qty+=qty;else state.shop.push({id:Date.now()+Math.random(),name,qty,unit,done:false})}
function toggleShop(id){let item=state.shop.find(x=>x.id===id);if(!item)return;if(!item.done){openModal('buy',id)}else{item.done=false;render();save()}}
function removeShop(id){state.shop=state.shop.filter(x=>x.id!==id);render();save()};function removeDone(){state.shop=state.shop.filter(x=>!x.done);render();save()}
function addMissing(id){let r=recipes.find(x=>x.id===id),n=state.servings,count=0;for(const x of needs(r,n)){let lack=Math.max(0,x.need-x.have);if(lack>0){addShop(x.name,lack,x.unit);count++}}closeModal();render();save();notify(count?`🛒 ${count} eksik malzeme market listende`:'Tüm malzemeler dolabında!')}
function deduct(name,unit,amount){let stocks=state.stock.filter(x=>x.name===name&&x.unit===unit).sort((a,b)=>a.expires.localeCompare(b.expires));for(let s of stocks){let n=Math.min(s.qty,amount);s.qty-=n;amount-=n;if(amount<=0)break}state.stock=state.stock.filter(x=>x.qty>0)}
function cook(id,meal=null){let r=recipes.find(x=>x.id===id),n=state.servings;if(!r)return;const missing=needs(r,n).filter(x=>x.have<x.need);if(missing.length&&!confirm(`Eksik malzemeler var: ${missing.map(x=>x.name).join(', ')}. Yine de yemeği yaptın mı?`))return;let used=(meal||state.chosenMeal||'').toString();if(!['Kahvaltı','Öğle','Akşam'].includes(used))used=r.cat==='Kahvaltı'?'Kahvaltı':'Akşam';needs(r,n).forEach(x=>deduct(x.name,x.unit,x.need));state.logs.push({id:Date.now(),date:today(),recipe:r.id,name:r.name,meal:used,kcal:r.kcal*n,pro:r.pro*n});state.chosenMeal=null;closeModal();save();render();notify(`✓ ${r.name} kaydedildi, stoklar güncellendi`)}
function chooseRecipe(id){const context=state.modal?.id;if(String(context).startsWith('plan|')){let date=context.split('|')[1];state.plan.push({date,recipe:id});closeModal();render();save();notify('Tarif planına eklendi')}else{closeModal();openModal('recipe',id);state.chosenMeal=context}}
function planThis(id){state.plan.push({date:today(),recipe:id});closeModal();render();save();notify('Bugünün planına eklendi')}
function candidateCost(r,counts){let total=0;for(let [name,q,unit] of r.ing){let u=priceFor(name,unit);if(u!==null)total+=u*q/r.serv}return total}
function generatePlan(){const base=sortedRecipes().filter(r=>!state.profile.exclude.some(ex=>r.ing.some(i=>normal(i[0]).includes(normal(ex))))),breakfast=base.filter(x=>x.cat==='Kahvaltı'),mains=base.filter(x=>x.cat==='Ana yemek');if(!breakfast.length||!mains.length)return notify('Tarif bulunamadı. Tercihlerini kontrol et.');let plan=[],spent=0,chosen={};let slots=state.profile.meals<=2?2:3;let target=state.budget*.9;for(let i=0;i<7;i++){let d=addDays(i);for(let k=0;k<slots;k++){let choices=k===0?breakfast:mains;let ranked=choices.map(r=>{let c=candidateCost(r);let repetition=chosen[r.id]||0;let affordable=(spent+c<=target)?0:80;return {r,c,score:Math.abs(r.kcal-state.profile.cal/slots)/90+repetition*(state.profile.repeat==='Evet'?1.5:state.profile.repeat==='Hayır'?30:7)+affordable+c/Math.max(1,state.budget)*50}}).sort((a,b)=>a.score-b.score);let pick=ranked[0];plan.push({date:d,recipe:pick.r.id});chosen[pick.r.id]=(chosen[pick.r.id]||0)+1;spent+=pick.c}}state.plan=plan;save();render();notify('✦ Menü oluşturuldu; bütçe tahmini fiyatı eksik ürünlerde kesin değildir.')}
function makeShopFromPlan(){if(!state.plan.length){notify('Önce haftalık plan oluştur.');go('plan');return}let totals={};for(let p of state.plan){let r=recipes.find(x=>x.id===p.recipe);if(!r)continue;for(let [name,q,unit] of r.ing){let key=name+'|'+unit;totals[key]=(totals[key]||0)+q/r.serv}}let count=0;for(let [key,total] of Object.entries(totals)){let [name,unit]=key.split('|');let lack=Math.max(0,total-qtyOf(name,unit));if(lack>.001){let old=state.shop.find(x=>!x.done&&x.name===name&&x.unit===unit);if(old)old.qty=Math.max(old.qty,lack);else addShop(name,+lack.toFixed(1),unit);count++}}save();go('shop');notify(count?`${count} eksik ürün hesaplandı`:'Planın için bütün malzemeler evde!')}
function exportData(){let blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mise-verilerim.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function resetAll(){if(!confirm('Bütün stok, plan ve tercihlerin silinsin mi?'))return;localStorage.removeItem('mise_state');location.reload()}
// For an immediate hands-on demonstration, onboarding ends with example stock that can be edited/deleted.
render();
